"""Build the versioned docs site.

Usage: python .github/scripts/build_docs_site.py [--out DIR] [--checkout-ref REF]
       [--preview REF]

.github/docs-versions.json lists the release lines, the git ref each one is
built from, and which line is stable. The site comes out like this:

  /               The stable line, built a second time, so every address from
                  before the docs were versioned still works. Canonical links
                  and sitemap.xml point here.
  /4.x/, /5.0/    One build per line, with Material's version selector. Each
                  page's canonical link names the same page at the root. A page
                  the stable line doesn't have points at the home page instead,
                  and gets noindex. A line that isn't stable shows a banner.
  /stable/        Redirects to the same page at the root.
  /versions.json  The list Material's version selector reads.

Each line is built from its own ref, with the docs toolchain installed from
this checkout. The version selector, the banner and the selector on the root
copy are added here at build time, so a ref needs nothing from this script to
be built. That is why release/4.x can stay as it was at v4.1.0.

--checkout-ref REF builds the line whose ref is REF from this working tree
instead of fetching it, so a pull request is checked with its own changes.
--preview REF adds a line called "preview" built from REF ("." is this
working tree). Pull requests use it to check a site with two lines.
"""

import argparse
import gzip
import io
import json
import os
import re
import shutil
import subprocess
import sys
import tarfile
import tempfile
from pathlib import Path
from typing import Any

import yaml

ROOT = Path(__file__).resolve().parents[2]
VERSIONS_FILE = ROOT / ".github" / "docs-versions.json"
NAME = re.compile(r"^[0-9]+\.(x|[0-9]+)$")
OVERRIDES = ".versioned-overrides"

# Added to the ref's own templates. The outdated block only shows on a line
# that isn't stable; Material decides that from versions.json in the browser.
WRAPPER = """{% extends "PARENT" %}
{#- Generated by .github/scripts/build_docs_site.py. -#}

{% block outdated %}
  {%- set line = config.extra.docs_version -%}
  You're reading the docs for {{ config.site_name }} {{ line.title }}.
  The stable release line is {{ line.stable_title }}:
  {%- set stable = page.canonical_url if page and page.canonical_url else "" %}
  <a href="{{ stable or config.site_url }}">read its docs</a>.
{% endblock %}

{% block extrahead %}
  {{ super() }}
  <style>
    /* Material dims the alias and keeps the theme's link colour in the
       banner. Both fail WCAG AA contrast on this palette. */
    .md-version__alias { opacity: 1; }
    [data-md-component="outdated"] .md-banner__inner a {
      color: inherit;
      text-decoration: underline;
    }
  </style>
{% endblock %}

{% block scripts %}
  {{ super() }}
  <script>
    /* Material labels the selector button "Select version", which hides the
       version it shows from screen readers (WCAG 2.5.3). Let the visible
       text name it, and keep the hint as a tooltip. */
    (() => {
      const fix = () => {
        const button = document.querySelector(".md-version__current[aria-label]");
        if (!button) return false;
        button.title = button.getAttribute("aria-label");
        button.removeAttribute("aria-label");
        return true;
      };
      if (fix()) return;
      const observer = new MutationObserver(() => fix() && observer.disconnect());
      observer.observe(document.body, {childList: true, subtree: true});
    })();
  </script>
  {%- if config.extra.docs_version.root %}
  <script>
    /* The copy of the stable docs at the site root. Material's selector
       looks for versions.json one directory up, which is outside this site,
       so this draws the same selector from the versions.json next to it. */
    (() => {
      const config = JSON.parse(document.getElementById("__config").textContent);
      const base = new URL(config.base, location.href);
      const topic = document.querySelector(".md-header__topic");
      if (!topic || document.querySelector(".md-version")) return;
      const here = location.pathname.startsWith(base.pathname)
        ? location.pathname.slice(base.pathname.length) : "";
      const el = (tag, attrs, ...children) => {
        const node = document.createElement(tag);
        Object.entries(attrs).forEach(([k, v]) => node.setAttribute(k, v));
        node.append(...children);
        return node;
      };
      const label = (v) => [v.title, ...(v.aliases.length
        ? [el("span", {class: "md-version__alias"}, v.aliases[0])] : [])];
      const go = async (event, home) => {
        event.preventDefault();
        let target = home;
        try {
          const xml = await (await fetch(new URL("sitemap.xml", home))).text();
          const pages = [...xml.matchAll(/<loc>([^<]*)<\\/loc>/g)]
            .map((m) => new URL(m[1]).pathname);
          if (pages.includes(base.pathname + here)) target = new URL(here, home);
        } catch (error) {}
        location.href = target.href + location.hash;
      };
      fetch(new URL("versions.json", base))
        .then((response) => response.json())
        .then((versions) => {
          const current = versions.find((v) => v.aliases.includes("stable"));
          if (!current) return;
          const items = versions.map((v) => {
            const home = new URL(v.version + "/", base);
            const attrs = {href: home.href, class: "md-version__link"};
            const link = el("a", attrs, ...label(v));
            link.addEventListener("click", (event) => go(event, home));
            return el("li", {class: "md-version__item"}, link);
          });
          topic.append(el("div", {class: "md-version"},
            el("button", {class: "md-version__current", title: "Select version"},
              ...label(current)),
            el("ul", {class: "md-version__list"}, ...items)));
        })
        .catch(() => {});
    })();
  </script>
  {%- endif %}
{% endblock %}
"""

# Material's own copy calls new URL("..") without a base, which throws in
# every browser, so the banner never shows before the bundle loads.
OUTDATED = """<script>
  (() => {
    const el = document.querySelector("[data-md-component=outdated]");
    const base = new URL("{{ base_url }}", location.href);
    if (el && __md_get("__outdated", sessionStorage, base) === true) el.hidden = false;
  })();
</script>
"""

STUB = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Redirecting</title>
<meta name="robots" content="noindex">
<link rel="canonical" href="{canonical}">
<meta http-equiv="refresh" content="0; url={target}">
<script>location.replace("{target}" + location.hash)</script>
</head>
<body><p><a href="{target}">Go to the stable docs</a>.</p></body>
</html>
"""


class Loader(yaml.SafeLoader):
    """Reads mkdocs.yml, ignoring tags like !!python/name."""


Loader.add_multi_constructor("", lambda loader, suffix, node: None)


def load_versions(path: Path) -> dict[str, Any]:
    data = json.loads(path.read_text())
    names = [v["version"] for v in data["versions"]]
    for name in names:
        if not NAME.match(name):
            raise SystemExit(f"{path}: version {name!r} should look like 4.x or 5.0")
    if len(set(names)) != len(names):
        raise SystemExit(f"{path}: a version is listed twice")
    if data["stable"] not in names:
        raise SystemExit(f"{path}: stable is {data['stable']!r}, which isn't listed")
    if not data["site_url"].endswith("/"):
        raise SystemExit(f"{path}: site_url must end with /")
    return data


def run(*args: str, cwd: Path = ROOT, **kwargs: Any) -> subprocess.CompletedProcess:
    return subprocess.run(args, cwd=cwd, check=True, **kwargs)


def export(ref: str, dest: Path, checkout_ref: str) -> str:
    """Put the files of REF in DEST and return a description of where they came from."""
    dest.mkdir(parents=True)
    if ref in (".", checkout_ref):
        listing = run(
            "git",
            "ls-files",
            "-z",
            "--cached",
            "--others",
            "--exclude-standard",
            stdout=subprocess.PIPE,
        ).stdout.decode()
        for name in filter(None, listing.split("\0")):
            source = ROOT / name
            if source.is_file():
                (dest / name).parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, dest / name)
        return "this working tree"
    run("git", "fetch", "--quiet", "--depth=1", "--no-tags", "origin", ref)
    sha = (
        run("git", "rev-parse", "FETCH_HEAD", stdout=subprocess.PIPE)
        .stdout.decode()
        .strip()
    )
    archive = run("git", "archive", "--format=tar", sha, stdout=subprocess.PIPE).stdout
    with tarfile.open(fileobj=io.BytesIO(archive)) as tar:
        tar.extractall(dest, filter="data")
    return f"{ref} at {sha[:12]}"


def add_overrides(src: Path) -> None:
    """Wrap the ref's own templates with the versioning blocks."""
    config = yaml.load((src / "mkdocs.yml").read_text(), Loader=Loader)
    custom_dir = (config.get("theme") or {}).get("custom_dir")
    overrides = src / OVERRIDES
    if custom_dir:
        shutil.copytree(src / custom_dir, overrides)
    else:
        overrides.mkdir()
    parent = "base.html"
    if (overrides / "main.html").exists():
        (overrides / "main.html").rename(overrides / "_line_main.html")
        parent = "_line_main.html"
    (overrides / "main.html").write_text(WRAPPER.replace("PARENT", parent))
    partial = overrides / "partials" / "javascripts" / "outdated.html"
    partial.parent.mkdir(parents=True, exist_ok=True)
    partial.write_text(OUTDATED)


def build(
    src: Path, out: Path, ref: str, extra: dict[str, Any], selector: bool
) -> None:
    overlay: dict[str, Any] = {
        "INHERIT": "mkdocs.yml",
        "theme": {"custom_dir": OVERRIDES},
        "extra": {"docs_version": extra},
    }
    if ref != ".":
        overlay["edit_uri"] = f"edit/{ref}/docs/"
    if selector:
        overlay["extra"]["version"] = {
            "provider": "mike",
            "default": "stable",
            "alias": True,
        }
    config = src / "mkdocs.versioned.yml"
    config.write_text(yaml.safe_dump(overlay, sort_keys=False))
    env = {**os.environ, "NO_MKDOCS_2_WARNING": "1"}
    run(
        sys.executable,
        "-m",
        "mkdocs",
        "build",
        "--strict",
        "--quiet",
        "-f",
        str(config),
        "-d",
        str(out),
        cwd=src,
        env=env,
    )


def page_file(site: Path, url: str, site_url: str) -> Path:
    rel = url[len(site_url) :]
    return site / rel / "index.html" if rel.endswith("/") or not rel else site / rel


def retarget(line: Path, root: Path, site_url: str) -> int:
    """Point pages the stable line lacks at the home page, and add noindex."""
    canonical = re.compile(r'<link rel="canonical" href="([^"]+)">')
    missing = set()
    for html in line.rglob("*.html"):
        text = html.read_text()
        match = canonical.search(text)
        if not match:
            continue
        url = match.group(1)
        if not url.startswith(site_url):
            raise SystemExit(f"{html}: canonical link {url} is outside {site_url}")
        if page_file(root, url, site_url).exists():
            continue
        missing.add(url)
        text = text.replace(f'"{url}"', f'"{site_url}"')
        text = text.replace(
            "<head>", '<head>\n    <meta name="robots" content="noindex">', 1
        )
        html.write_text(text)
    sitemap = line / "sitemap.xml"
    if sitemap.exists():
        xml = re.sub(
            r"\s*<url>\s*<loc>([^<]*)</loc>.*?</url>",
            lambda m: "" if m.group(1) in missing else m.group(0),
            sitemap.read_text(),
            flags=re.S,
        )
        sitemap.write_text(xml)
        with gzip.open(line / "sitemap.xml.gz", "wb") as gz:
            gz.write(xml.encode())
    return len(missing)


def add_stable_redirects(root: Path, site_url: str) -> None:
    for page in sorted(root.rglob("index.html")):
        rel = page.parent.relative_to(root).as_posix()
        rel = "" if rel == "." else rel + "/"
        if rel.startswith("assets/"):
            continue
        target = "../" * (rel.count("/") + 1) + rel
        stub = root / "stable" / rel / "index.html"
        stub.parent.mkdir(parents=True, exist_ok=True)
        stub.write_text(STUB.format(canonical=site_url + rel, target=target))


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--out", type=Path, default=ROOT / "site")
    parser.add_argument("--checkout-ref", default="")
    parser.add_argument("--preview", metavar="REF")
    parser.add_argument("--versions", type=Path, default=VERSIONS_FILE)
    args = parser.parse_args()
    data = load_versions(args.versions)
    site_url = data["site_url"]
    lines = list(data["versions"])
    if args.preview:
        lines.insert(0, {"version": "preview", "title": "preview", "ref": args.preview})
    titles = {v["version"]: v["title"] for v in lines}
    out = args.out.resolve()
    with tempfile.TemporaryDirectory() as tmp:
        work = Path(tmp)
        sources = {}
        for line in lines:
            src = work / "src" / line["version"]
            origin = export(line["ref"], src, args.checkout_ref)
            config = yaml.load((src / "mkdocs.yml").read_text(), Loader=Loader)
            if config.get("site_url") != site_url:
                raise SystemExit(f"{origin}: site_url isn't {site_url}")
            add_overrides(src)
            sources[line["version"]] = src
            print(f"{line['version']}: {origin}")
        stable = data["stable"]
        extra = {"stable_title": titles[stable]}
        ref_of = {v["version"]: v["ref"] for v in lines}
        build(
            sources[stable],
            work / "root",
            ref_of[stable],
            {**extra, "title": titles[stable], "root": True},
            selector=False,
        )
        root = work / "root"
        for name in [*titles, "stable", "versions.json"]:
            if (root / name).exists():
                raise SystemExit(
                    f"The docs have a page at /{name}, which a version needs"
                )
        for line in lines:
            name = line["version"]
            build(
                sources[name],
                work / "lines" / name,
                line["ref"],
                {**extra, "title": line["title"], "root": False},
                selector=True,
            )
            dropped = retarget(work / "lines" / name, root, site_url)
            print(f"{name}: built, {dropped} pages the stable line doesn't have")
        add_stable_redirects(root, site_url)
        for name in titles:
            shutil.copytree(work / "lines" / name, root / name)
        versions = [
            {
                "version": v["version"],
                "title": v["title"],
                "aliases": ["stable"] if v["version"] == stable else [],
            }
            for v in lines
        ]
        (root / "versions.json").write_text(json.dumps(versions, indent=2) + "\n")
        if out.exists():
            shutil.rmtree(out)
        shutil.copytree(root, out)
    print(f"Site in {out}: stable is {stable}, lines {', '.join(titles)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
